local Window=getgenv().SORU_Window if not Window then return end
local MainAPI=Window:Tab({Title="Main"}) local MiscAPI=Window:Tab({Title="Misc"}) local EspAPI=Window:Tab({Title="Esp"}) local AnimalAPI=Window:Tab({Title="Animal"}) local EventAPI=Window:Tab({Title="Event"})
repeat task.wait() until Window.Tabs and Window.Tabs["Main"] and Window.Tabs["Misc"] and Window.Tabs["Esp"] and Window.Tabs["Animal"] and Window.Tabs["Event"] and Window.Gui:FindFirstChild("Root")

local Players=game:GetService("Players") local TweenService=game:GetService("TweenService") local ProximityPromptService=game:GetService("ProximityPromptService")
local UserInputService=game:GetService("UserInputService") local VIM=game:GetService("VirtualInputManager") local RS=game:GetService("ReplicatedStorage") local RunService=game:GetService("RunService")
local plr=Players.LocalPlayer
local V3,V2,CF,C3=Vector3.new,Vector2.new,CFrame.new,Color3.new

local function getTabScroll(name) local t=Window.Tabs[name] if t and t.frame then return t.frame:FindFirstChildOfClass("ScrollingFrame") or t.frame end return nil end
local mainFrame=getTabScroll("Main") local miscFrame=getTabScroll("Misc") local espFrame=getTabScroll("Esp") local animalFrame=getTabScroll("Animal") local eventFrame=getTabScroll("Event")
repeat task.wait() until mainFrame and miscFrame and espFrame and animalFrame and eventFrame
local function clearFrame(f) for _,v in ipairs(f:GetChildren()) do if v:IsA("GuiObject") and not v:IsA("UIListLayout") and not v:IsA("UIPadding") then v:Destroy() end end end
clearFrame(mainFrame) clearFrame(miscFrame) clearFrame(espFrame) clearFrame(animalFrame) clearFrame(eventFrame)

local root=Window.Gui:FindFirstChild("Root")
local SAFE_BASE_POS=V3(-75,3.5,-7.4) local HELPER_DROP_POS=V3(-105.2,3.7,-6.2) local OFFSET_DIST=3 local RANGE=15
local SLIDER_MIN,SLIDER_MAX=16,500 local sliderSpeed=16 local walkSpeedSliderRef=nil
local function getRealHumanoidSpeed() local hum=plr.Character and plr.Character:FindFirstChildOfClass("Humanoid") if hum then return hum.WalkSpeed end return sliderSpeed end
local ACCENT=Color3.fromRGB(139,92,246) local ACCENT2=Color3.fromRGB(99,102,241) local DIM=Color3.fromRGB(148,140,180)
local function tw(o,p,t,s) return TweenService:Create(o,TweenInfo.new(t or 0.3,s or Enum.EasingStyle.Quad,Enum.EasingDirection.Out),p) end

local RARITY_SCORE={["Common"]=1,["Uncommon"]=2,["Rare"]=3,["Epic"]=4,["Legendary"]=5,["Mythic"]=6,["Secret"]=7,["Godly"]=8,["Cosmic"]=9,["Divine"]=10,["Celestial"]=11}
local RARITY_COLOR={["Common"]=Color3.fromRGB(180,180,180),["Uncommon"]=Color3.fromRGB(92,255,92),["Rare"]=Color3.fromRGB(85,170,255),["Epic"]=Color3.fromRGB(170,85,255),["Legendary"]=Color3.fromRGB(255,180,0),["Mythic"]=Color3.fromRGB(255,60,60),["Secret"]=Color3.fromRGB(0,0,0),["Godly"]=Color3.fromRGB(255,223,0),["Cosmic"]=Color3.fromRGB(0,255,255),["Divine"]=Color3.fromRGB(255,255,255),["Celestial"]=Color3.fromRGB(255,120,255)}
local function getRarityColor(r) return RARITY_COLOR[r] or ACCENT end
local rarityNames={} local rf=RS:FindFirstChild("Rarities") if rf then for _,c in ipairs(rf:GetChildren()) do table.insert(rarityNames,c.Name) end else rarityNames={"Common","Rare","Epic","Legendary","Mythic","Secret"} end
local function getRarityScore(n) if RARITY_SCORE[n] then return RARITY_SCORE[n] end for i,v in ipairs(rarityNames) do if v==n then return i end end return 0 end
local function getBasePos(m) local b if m.PrimaryPart then b=m.PrimaryPart.Position else local ok,cf=pcall(function() return m:GetPivot() end) if ok then b=V3(cf.X,cf.Y,cf.Z) else for _,v in ipairs(m:GetDescendants()) do if v:IsA("BasePart") then b=v.Position break end end end end return b end
local function getOffsetPos(m) local base=getBasePos(m) if not base then return nil,nil end local hrp=plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") local dir=hrp and V3(hrp.Position.X-base.X,0,hrp.Position.Z-base.Z) or V3(0,0,1) if dir.Magnitude<1 then dir=V3(0,0,1) end return V3(base.X,3.5,base.Z)+dir.Unit*OFFSET_DIST,V3(base.X,3.5,base.Z) end
local function getZoneBuildsFolder() local b=workspace:FindFirstChild("Build") if b then local zb=b:FindFirstChild("ZoneBuilds") if zb then return zb end end return workspace:FindFirstChild("ZoneBuilds") or workspace:FindFirstChild("Build") end
local function getAnimalZone(model) local pos=getBasePos(model) if not pos then return "Unknown" end local zb=getZoneBuildsFolder() if not zb then return "Unknown" end local closest="Unknown" local minD=math.huge for _,z in ipairs(zb:GetChildren()) do if z:IsA("Model") then local zp=getBasePos(z) if zp then local d=(V3(pos.X,0,pos.Z)-V3(zp.X,0,zp.Z)).Magnitude if d<minD then minD=d closest=z.Name end end end end return closest end
local function getCashPerSecond(model) for _,v in ipairs(model:GetDescendants()) do if v.Name=="CashPerSecond" and v:IsA("TextLabel") then return v.Text end end return "?" end
local function parseCash(text) if not text then return 0 end local s=tostring(text):gsub("%$",""):gsub("/s",""):gsub("/sec",""):gsub(" ",""):gsub(",",""):upper() local num=tonumber(s:match("[%d%.]+")) if not num then return 0 end if s:find("K") then num*=1000 elseif s:find("M") then num*=1000000 elseif s:find("B") then num*=1000000000 elseif s:find("T") then num*=1000000000000 end return num end
local function parseFilterInput(text) if not text or text=="" then return 0 end return parseCash(text) end

local defendMode="None" local attackEnabled=false local minCashFilter=0 local bigEggPriority=true
local selectedFollowPlayer=nil local followEnabled=false
local espEnabled=false local selectedEspRarity={} local espCache={}
local function getWalkSpeed() return sliderSpeed end
do local hum=plr.Character and plr.Character:FindFirstChildOfClass("Humanoid") if hum then sliderSpeed=hum.WalkSpeed end end

-- HALLOWEEN VARS
local halloweenStay=3 local halloweenEnabled=false local halloweenActive=false local lastClueSeen=0 local hasResetThisEvent=false local cachedCluePos=nil

local function findDropButton() for _,v in ipairs(plr.PlayerGui:GetDescendants()) do if v:IsA("TextButton") and (v.Name:lower():find("drop") or v.Text:lower():find("drop")) then return v end end return nil end
local function isDropVisible() local btn=findDropButton() if not btn then return false end if not btn.Visible then return false end local cur=btn.Parent while cur and cur~=plr.PlayerGui do if cur:IsA("GuiObject") and not cur.Visible then return false end cur=cur.Parent end return true end
local function fireDropNow() local dropBtn=findDropButton() if dropBtn then pcall(function() dropBtn:Activate() end) end local remote=RS:FindFirstChild("DropCarriedRemote") or RS:FindFirstChild("DropCarriedRemote",true) or RS:FindFirstChild("DropCarried",true) if remote then pcall(function() remote:FireServer() end) end end
local function getClosestAnimalToHRP(maxDist) local hrp=plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") if not hrp then return nil end local closest=nil local minD=maxDist or 8 local folder=workspace:FindFirstChild("AnimalPickups") if folder then for _,m in ipairs(folder:GetChildren()) do if m:IsA("Model") then local pos=getBasePos(m) if pos then local d=(V3(hrp.Position.X,0,hrp.Position.Z)-V3(pos.X,0,pos.Z)).Magnitude if d<minD then minD=d closest=m end end end end end return closest end
local function isCarryingTarget(targetModel) if not isDropVisible() then return false end local closest=getClosestAnimalToHRP(8) if not closest then return true end if closest==targetModel then return true end if closest.Name==targetModel.Name and closest:GetAttribute("Rarity")==targetModel:GetAttribute("Rarity") then return true end return false end

local function walkDirect(targetPos,lookAt,keepRot) local char=plr.Character local hrp=char and char:FindFirstChild("HumanoidRootPart") if not hrp or not targetPos then return end if lookAt then lookAt=V3(lookAt.X,targetPos.Y,lookAt.Z) end pcall(function() hrp.AssemblyLinearVelocity=Vector3.zero hrp.AssemblyAngularVelocity=Vector3.zero end) local function distLeft() return (V3(hrp.Position.X,0,hrp.Position.Z)-V3(targetPos.X,0,targetPos.Z)).Magnitude end if distLeft()<1.2 then return end while distLeft()>1.2 do if not char or not hrp.Parent then break end if followEnabled and selectedFollowPlayer then local t=Players:FindFirstChild(selectedFollowPlayer) if t and t.Character and t.Character:FindFirstChild("HumanoidRootPart") then else if getRealHumanoidSpeed()<1 then break end end end local ws=getWalkSpeed() local cur=V3(hrp.Position.X,targetPos.Y,hrp.Position.Z) local dir=V3(targetPos.X-cur.X,0,targetPos.Z-cur.Z) if dir.Magnitude<0.1 then break end dir=dir.Unit local dt=RunService.Heartbeat:Wait() local step=dir*ws*dt if step.Magnitude>distLeft() then step=dir*distLeft() end local newPos=cur+step local cf=keepRot and CF(newPos)*(hrp.CFrame-hrp.CFrame.Position) or (lookAt and CF(newPos,lookAt) or CFrame.lookAt(newPos,newPos+dir)) hrp.CFrame=cf hrp.AssemblyLinearVelocity=Vector3.zero end end
local function walkDirectFallback(targetPos,keepRot,originalAnimal) local char=plr.Character local hrp=char and char:FindFirstChild("HumanoidRootPart") if not hrp or not targetPos then return false end pcall(function() hrp.AssemblyLinearVelocity=Vector3.zero hrp.AssemblyAngularVelocity=Vector3.zero end) local function distLeft() return (V3(hrp.Position.X,0,hrp.Position.Z)-V3(targetPos.X,0,targetPos.Z)).Magnitude end if distLeft()<1.2 then return true end while distLeft()>1.2 do if not char or not hrp.Parent then return false end if not isDropVisible() then if originalAnimal and originalAnimal.Parent then local p,b=getOffsetPos(originalAnimal) if p then walkDirect(p,b,false) end end return false end local ws=getWalkSpeed() local cur=V3(hrp.Position.X,targetPos.Y,hrp.Position.Z) local dir=V3(targetPos.X-cur.X,0,targetPos.Z-cur.Z) if dir.Magnitude<0.1 then break end dir=dir.Unit local dt=RunService.Heartbeat:Wait() local step=dir*ws*dt if step.Magnitude>distLeft() then step=dir*distLeft() end local newPos=cur+step local cf=keepRot and CF(newPos)*(hrp.CFrame-hrp.CFrame.Position) or CFrame.lookAt(newPos,newPos+dir) hrp.CFrame=cf hrp.AssemblyLinearVelocity=Vector3.zero end return true end
local function walkDefendFallback(targetPos,mode,originalAnimal) if mode=="None" or not mode then return walkDirectFallback(targetPos,true,originalAnimal) end local hrp=plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") if not hrp then return false end local start=V3(hrp.Position.X,targetPos.Y,hrp.Position.Z) local dir=(targetPos-start) local dist=V3(dir.X,0,dir.Z).Magnitude if dist<5 then return walkDirectFallback(targetPos,true,originalAnimal) end dir=V3(dir.X,0,dir.Z).Unit local perp=V3(-dir.Z,0,dir.X) local points={} if mode=="ZigZag" then for i=1,4 do local t=i/5 local baseP=start:Lerp(targetPos,t) local offset=(i%2==0 and 1 or -1)*10 table.insert(points,baseP+perp*offset) end elseif mode=="Random" then for i=1,4 do local t=i/5 local baseP=start:Lerp(targetPos,t) table.insert(points,baseP+perp*math.random(-12,12)) end elseif mode=="Circle" then for i=1,6 do local t=i/7 local baseP=start:Lerp(targetPos,t) local ang=i*60 table.insert(points,baseP+V3(math.cos(math.rad(ang))*8,0,math.sin(math.rad(ang))*8)) end elseif mode=="Juke" then for i=1,5 do local t=i/6 local baseP=start:Lerp(targetPos,t) local offset=(i%2==0 and 14 or -14)+math.random(-4,4) table.insert(points,baseP+perp*offset) end end for _,p in ipairs(points) do local ok=walkDirectFallback(p,true,originalAnimal) if not ok then return false end task.wait(0.05) end return walkDirectFallback(targetPos,true,originalAnimal) end
local function walkToSafeBaseFallback(originalAnimal) local ok=walkDefendFallback(V3(-75,3.5,-7.4),defendMode,originalAnimal) if not ok then return false end ok=walkDefendFallback(SAFE_BASE_POS,defendMode,originalAnimal) return ok end
local function walkToSafeBase() walkDirect(V3(-75,3.5,-7.4),nil,true) walkDirect(SAFE_BASE_POS,nil,true) end

local function setupViewportModel(vp,model) vp:ClearAllChildren() local clone=model:Clone() for _,d in ipairs(clone:GetDescendants()) do if d:IsA("Script") or d:IsA("LocalScript") or d:IsA("ProximityPrompt") or d:IsA("ParticleEmitter") or d:IsA("BillboardGui") or d:IsA("SurfaceGui") or d:IsA("Highlight") then d:Destroy() end if d:IsA("BasePart") then d.Anchored=true d.CanCollide=false end end pcall(function() clone:PivotTo(CF(0,0,0)) end) local _,size=clone:GetBoundingBox() clone.Parent=vp local cam=Instance.new("Camera") cam.FieldOfView=30 cam.CFrame=CFrame.new(V3(1.2,0.8,2.5)*math.clamp(math.max(size.X,size.Y,size.Z),1,5),V3(0,0,0)) cam.Parent=vp vp.CurrentCamera=cam end
local function makeBigPrompt(p) if not p:IsA("ProximityPrompt") then return end pcall(function() p.HoldDuration=0 p.MaxActivationDistance=RANGE p.RequiresLineOfSight=false p.KeyboardKeyCode=Enum.KeyCode.E p.Exclusivity=Enum.ProximityPromptExclusivity.OnePerButton end) end
local function firePrompt(p) if not p:IsA("ProximityPrompt") then return end makeBigPrompt(p) if fireproximityprompt then pcall(fireproximityprompt,p,0) end pcall(function() p:InputHoldBegin() task.wait(0.05) p:InputHoldEnd() end) end
local function fireSteal(m) if not m or not m.Parent then return end for _,v in ipairs(m:GetDescendants()) do if v:IsA("ProximityPrompt") then firePrompt(v) end end end
local function touchSteal(m) if not m or not m.Parent then return end local hrp=plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") local part=m.PrimaryPart or m:FindFirstChildWhichIsA("BasePart") if hrp and part then pcall(function() firetouchinterest(hrp,part,0) task.wait(0.02) firetouchinterest(hrp,part,1) end) end end
local function pressE() pcall(function() VIM:SendKeyEvent(true,Enum.KeyCode.E,false,game) task.wait(0.05) VIM:SendKeyEvent(false,Enum.KeyCode.E,false,game) end) end
local function getClosestPlayerToModel(model,maxDist) local pos=getBasePos(model) if not pos then return nil end local closest=nil local minD=maxDist or 20 for _,p in ipairs(Players:GetPlayers()) do if p~=plr and p.Character and p.Character:FindFirstChild("HumanoidRootPart") then local hrp=p.Character.HumanoidRootPart local d=(V3(hrp.Position.X,0,hrp.Position.Z)-V3(pos.X,0,pos.Z)).Magnitude if d<minD then minD=d closest=p end end end return closest end
local function equipBat() local char=plr.Character if not char then return nil end local bat=char:FindFirstChildWhichIsA("Tool") if bat and bat.Name:lower():find("bat") then return bat end for _,t in ipairs(plr.Backpack:GetChildren()) do if t:IsA("Tool") and t.Name:lower():find("bat") then t.Parent=char return t end end for _,t in ipairs(plr.Backpack:GetChildren()) do if t:IsA("Tool") then t.Parent=char return t end end return char:FindFirstChildOfClass("Tool") end
local function attackCarrier(carrier) if not attackEnabled then return end if not carrier or not carrier.Character then return end local char=carrier.Character local hrp=char:FindFirstChild("HumanoidRootPart") if not hrp then return end for i=1,20 do if not char.Parent or not attackEnabled then break end local myHrp=plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") if not myHrp then break end local pred=hrp.Position+hrp.CFrame.LookVector*5 pred=V3(pred.X,3.5,pred.Z) walkDirect(pred,hrp.Position,false) local bat=equipBat() if bat then pcall(function() bat:Activate() end) pcall(function() VIM:SendMouseButtonEvent(0,0,0,true,game,0) task.wait(0.05) VIM:SendMouseButtonEvent(0,0,0,false,game,0) end) end task.wait(0.15) local dist=(V3(myHrp.Position.X,0,myHrp.Position.Z)-V3(hrp.Position.X,0,hrp.Position.Z)).Magnitude if dist>30 then break end end end

local function showStealNotif(model) if not model or not model.Parent then return end local rarity=model:GetAttribute("Rarity") or "Unknown" local weight=model:GetAttribute("WeightKg") or model:GetAttribute("Weight") or 0 Window.Notify("STEAL • "..model.Name:upper(),tostring(weight).." KG • "..string.upper(rarity).." • "..getCashPerSecond(model),ACCENT,3) end
local stealMode="Normal"
local function stealMethod(targetModel) if not targetModel or not targetModel.Parent then return end showStealNotif(targetModel) local lastPos=getBasePos(targetModel) local tries=0 while tries<8 and targetModel.Parent do if isDropVisible() then if not isCarryingTarget(targetModel) then fireDropNow() task.wait(0.35) tries+=1 continue else break end end local curPos=getBasePos(targetModel) if curPos and lastPos and (curPos-lastPos).Magnitude>2 then local carrier=getClosestPlayerToModel(targetModel,20) if carrier and attackEnabled then attackCarrier(carrier) end end lastPos=curPos local p,b=getOffsetPos(targetModel) if p then walkDirect(p,b,false) end touchSteal(targetModel) fireSteal(targetModel) pressE() task.wait(0.25) tries+=1 if isDropVisible() and not isCarryingTarget(targetModel) then fireDropNow() task.wait(0.3) end end if not isDropVisible() then walkToSafeBase() return end if not isCarryingTarget(targetModel) then fireDropNow() task.wait(0.3) return end if stealMode=="Helper" then local ok=walkDefendFallback(HELPER_DROP_POS,defendMode,targetModel) if not ok then return end if not isCarryingTarget(targetModel) then fireDropNow() return end task.wait(0.15) fireDropNow() task.wait(0.2) walkToSafeBaseFallback(targetModel) else local ok=walkToSafeBaseFallback(targetModel) if not ok then return end end end

-- ESP
local function removeAnimalEsp(model) local data=espCache[model] if data then pcall(function() if data.hl then data.hl:Destroy() end end) pcall(function() if data.bb then data.bb:Destroy() end end) espCache[model]=nil end end
local function clearAllEsp() for m,_ in pairs(espCache) do removeAnimalEsp(m) end table.clear(espCache) end
local function createAnimalEsp(model) if not model or not model.Parent then return end if espCache[model] then return end if not model:IsA("Model") then return end local rarity=model:GetAttribute("Rarity") or "Unknown" if next(selectedEspRarity)~=nil and not selectedEspRarity[rarity] then return end local adornee=model.PrimaryPart or model:FindFirstChildWhichIsA("BasePart") if not adornee then return end local color=getRarityColor(rarity) local hl=Instance.new("Highlight") hl.Name="SoruEspHL" hl.Adornee=model hl.FillColor=color hl.OutlineColor=color hl.FillTransparency=0.65 hl.OutlineTransparency=0 hl.DepthMode=Enum.HighlightDepthMode.AlwaysOnTop hl.Parent=model local bb=Instance.new("BillboardGui") bb.Name="SoruEspBB" bb.Adornee=adornee bb.Size=UDim2.fromOffset(165,56) bb.StudsOffset=V3(0,4.2,0) bb.AlwaysOnTop=true bb.Parent=adornee local f=Instance.new("Frame",bb) f.Size=UDim2.new(1,0,1,0) f.BackgroundColor3=Color3.fromRGB(20,18,32) f.BackgroundTransparency=0.12 Instance.new("UICorner",f).CornerRadius=UDim.new(0,8) local st=Instance.new("UIStroke",f) st.Color=color st.Transparency=0.2 st.Thickness=1 local n=Instance.new("TextLabel",f) n.Size=UDim2.new(1,-8,0,14) n.Position=UDim2.new(0,5,0,4) n.BackgroundTransparency=1 n.Text=model.Name:upper() n.Font=Enum.Font.GothamBold n.TextSize=10 n.TextColor3=C3(1,1,1) n.TextXAlignment=Enum.TextXAlignment.Left n.TextTruncate=Enum.TextTruncate.AtEnd local rLbl=Instance.new("TextLabel",f) rLbl.Size=UDim2.new(1,-8,0,11) rLbl.Position=UDim2.new(0,5,0,18) rLbl.BackgroundTransparency=1 rLbl.Text=string.upper(rarity).." • "..getCashPerSecond(model) rLbl.Font=Enum.Font.GothamMedium rLbl.TextSize=9 rLbl.TextColor3=color rLbl.TextXAlignment=Enum.TextXAlignment.Left local w=model:GetAttribute("WeightKg") or model:GetAttribute("Weight") or 0 local zone=getAnimalZone(model) local wLbl=Instance.new("TextLabel",f) wLbl.Size=UDim2.new(1,-8,0,10) wLbl.Position=UDim2.new(0,5,0,30) wLbl.BackgroundTransparency=1 wLbl.Text=tostring(w).." KG • "..zone wLbl.Font=Enum.Font.GothamMedium wLbl.TextSize=8 wLbl.TextColor3=DIM wLbl.TextXAlignment=Enum.TextXAlignment.Left espCache[model]={hl=hl,bb=bb} end
local function refreshAllEsp() if not espEnabled then clearAllEsp() return end local folder=workspace:FindFirstChild("AnimalPickups") if not folder then return end for _,m in ipairs(folder:GetChildren()) do if m:IsA("Model") then local rarity=m:GetAttribute("Rarity") or "Unknown" local allowed=next(selectedEspRarity)==nil or selectedEspRarity[rarity] if allowed then createAnimalEsp(m) else removeAnimalEsp(m) end end end for m,_ in pairs(espCache) do if not m.Parent then removeAnimalEsp(m) end end end

local function getClosestClue() local hrp=plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") if not hrp then return nil,nil end local closest=nil local minD=math.huge local closestPos=nil local direct=workspace:FindFirstChild("DisguisedEggClue") if direct then local p=getBasePos(direct) if p then return direct,p end end for _,v in ipairs(workspace:GetDescendants()) do if v.Name=="DisguisedEggClue" then local pos=getBasePos(v) if pos then local d=(V3(hrp.Position.X,0,hrp.Position.Z)-V3(pos.X,0,pos.Z)).Magnitude if d<minD then minD=d closest=v closestPos=pos end end end end return closest,closestPos end

