local function getStealTargets() local folder=workspace:FindFirstChild("AnimalPickups") if not folder or next(selected)==nil then return {} end local out={} for _,m in ipairs(folder:GetChildren()) do if m:IsA("Model") and selected[m:GetAttribute("Rarity")] then if next(selectedZones)~=nil then local z=getAnimalZone(m) if not selectedZones[z] then continue end end if minCashFilter>0 then local cash=parseCash(getCashPerSecond(m)) if cash<minCashFilter then continue end end table.insert(out,m) end end table.sort(out,function(a,b) return getRarityScore(a:GetAttribute("Rarity") or "")>getRarityScore(b:GetAttribute("Rarity") or "") end) return out end

local stealOn=false
stealToggle.btn.MouseButton1Click:Connect(function() stealOn=not stealOn if stealOn then if next(selected)==nil then Window.Notify("ERROR","Pilih Rarity dulu!",Color3.fromRGB(248,113,113),3) stealOn=false return end tw(stealToggle.track,{BackgroundColor3=ACCENT},0.2):Play() tw(stealToggle.dot,{Position=UDim2.new(1,-21,0.5,-9)},0.25,Enum.EasingStyle.Back):Play() tw(stealToggle.accent,{BackgroundColor3=ACCENT},0.2):Play() walkToSafeBase() task.spawn(function() while stealOn do local list=getStealTargets() local found=#list>0 for _,m in ipairs(list) do if not stealOn then break end pcall(function() stealMethod(m) end) task.wait(0.5) end if not found then task.wait(0.8) end end end) else tw(stealToggle.track,{BackgroundColor3=Color3.fromRGB(34,30,50)},0.2):Play() tw(stealToggle.dot,{Position=UDim2.new(0,3,0.5,-9)},0.25,Enum.EasingStyle.Back):Play() tw(stealToggle.accent,{BackgroundColor3=Color3.fromRGB(60,55,80)},0.2):Play() stealOn=false end end)
attackToggle.btn.MouseButton1Click:Connect(function() attackEnabled=not attackEnabled if attackEnabled then tw(attackToggle.track,{BackgroundColor3=Color3.fromRGB(255,80,80)},0.2):Play() tw(attackToggle.dot,{Position=UDim2.new(1,-21,0.5,-9)},0.25,Enum.EasingStyle.Back):Play() tw(attackToggle.accent,{BackgroundColor3=Color3.fromRGB(255,80,80)},0.2):Play() Window.Notify("ATTACK","ON",Color3.fromRGB(255,80,80),2) else tw(attackToggle.track,{BackgroundColor3=Color3.fromRGB(34,30,50)},0.2):Play() tw(attackToggle.dot,{Position=UDim2.new(0,3,0.5,-9)},0.25,Enum.EasingStyle.Back):Play() tw(attackToggle.accent,{BackgroundColor3=Color3.fromRGB(60,55,80)},0.2):Play() Window.Notify("ATTACK","OFF",DIM,2) end end)

local extOn=false
panelToggle.btn.MouseButton1Click:Connect(function() extOn=not extOn if extOn then tw(panelToggle.track,{BackgroundColor3=ACCENT},0.2):Play() tw(panelToggle.dot,{Position=UDim2.new(1,-21,0.5,-9)},0.25,Enum.EasingStyle.Back):Play() tw(panelToggle.accent,{BackgroundColor3=ACCENT},0.2):Play() StealPanel:Show() refreshExternal() task.spawn(function() while extOn and StealPanel:IsOpen() do refreshExternal() task.wait(2) end end) else tw(panelToggle.track,{BackgroundColor3=Color3.fromRGB(34,30,50)},0.2):Play() tw(panelToggle.dot,{Position=UDim2.new(0,3,0.5,-9)},0.25,Enum.EasingStyle.Back):Play() tw(panelToggle.accent,{BackgroundColor3=Color3.fromRGB(60,55,80)},0.2):Play() StealPanel:Hide() end end)

local function getEggSize(model) for _,a in ipairs({"Size","EggSize","Scale","WeightKg","Weight","SizeMultiplier"}) do local v=model:GetAttribute(a) if typeof(v)=="number" then return v end end for _,d in ipairs(model:GetDescendants()) do if d:IsA("NumberValue") and d.Name:lower():find("size") then return d.Value end end local ok,_,sz=pcall(function() return model:GetBoundingBox() end) if ok and sz then return sz.Magnitude end return 0 end
local function getEggsInZone(zoneName) local zb=getZoneBuildsFolder() if not zb then return {} end local zoneModel=zb:FindFirstChild(zoneName) if not zoneModel then return {} end local eggsRoot=zoneModel:FindFirstChild("Eggs") or zoneModel local out={} for _,v in ipairs(eggsRoot:GetChildren()) do if v:IsA("Model") and v.Name:lower():find("egg") then table.insert(out,v) end end if #out==0 then for _,v in ipairs(eggsRoot:GetDescendants()) do if v:IsA("Model") and v.Name:lower():find("egg") then table.insert(out,v) end end end if bigEggPriority then table.sort(out,function(a,b) return getEggSize(a)>getEggSize(b) end) end return out end
local function getEggHealth(eggModel) if eggModel:GetAttribute("Health") then return eggModel:GetAttribute("Health") end for _,d in ipairs(eggModel:GetDescendants()) do local h=d:GetAttribute("Health") if h~=nil then return h end end return nil end
local function equipPickaxe() local char=plr.Character if not char then return nil end local tool=char:FindFirstChildOfClass("Tool") if tool and tool.Name:lower():find("pickaxe") then return tool end for _,t in ipairs(plr.Backpack:GetChildren()) do if t:IsA("Tool") and t.Name:lower():find("pickaxe") then t.Parent=char return t end end for _,t in ipairs(plr.Backpack:GetChildren()) do if t:IsA("Tool") then t.Parent=char return t end end return char:FindFirstChildOfClass("Tool") end

bigEggToggle.btn.MouseButton1Click:Connect(function() bigEggPriority=not bigEggPriority if bigEggPriority then tw(bigEggToggle.track,{BackgroundColor3=ACCENT},0.2):Play() tw(bigEggToggle.dot,{Position=UDim2.new(1,-21,0.5,-9)},0.25,Enum.EasingStyle.Back):Play() tw(bigEggToggle.accent,{BackgroundColor3=ACCENT},0.2):Play() Window.Notify("BIG EGG","Priority ON - Biggest First",ACCENT,2) else tw(bigEggToggle.track,{BackgroundColor3=Color3.fromRGB(34,30,50)},0.2):Play() tw(bigEggToggle.dot,{Position=UDim2.new(0,3,0.5,-9)},0.25,Enum.EasingStyle.Back):Play() tw(bigEggToggle.accent,{BackgroundColor3=Color3.fromRGB(60,55,80)},0.2):Play() Window.Notify("BIG EGG","OFF",DIM,2) end end)

local breakOn=false
eggToggle.btn.MouseButton1Click:Connect(function() breakOn=not breakOn if breakOn then if not selectedEggZone then breakOn=false Window.Notify("ERROR","Pilih Zone dulu!",Color3.fromRGB(248,113,113),2) return end tw(eggToggle.track,{BackgroundColor3=Color3.fromRGB(255,220,90)},0.25):Play() tw(eggToggle.dot,{Position=UDim2.new(1,-21,0.5,-9)},0.25,Enum.EasingStyle.Back):Play() tw(eggToggle.accent,{BackgroundColor3=Color3.fromRGB(255,220,90)},0.25):Play() task.spawn(function() while breakOn do if halloweenActive then task.wait(0.5) continue end local targets=getStealTargets() if #targets>0 then for _,m in ipairs(targets) do if not breakOn or halloweenActive then break end pcall(function() stealMethod(m) end) task.wait(0.3) end continue end local eggs=getEggsInZone(selectedEggZone) if #eggs==0 then task.wait(1) continue end for _,egg in ipairs(eggs) do if not breakOn or halloweenActive then break end if #getStealTargets()>0 then break end local pos,base=getOffsetPos(egg) if not pos then local b=getBasePos(egg) if b then pos=V3(b.X,3.5,b.Z+3) base=V3(b.X,3.5,b.Z) end end if not pos then continue end pcall(function() walkDirect(pos,base,false) equipPickaxe() while breakOn and not halloweenActive and egg.Parent do if #getStealTargets()>0 then break end local h=getEggHealth(egg) if h==nil or h<=0 then break end task.wait(0.15) end end) task.wait(0.2) end task.wait(0.5) end end) else tw(eggToggle.track,{BackgroundColor3=Color3.fromRGB(34,30,50)},0.25):Play() tw(eggToggle.dot,{Position=UDim2.new(0,3,0.5,-9)},0.25,Enum.EasingStyle.Back):Play() tw(eggToggle.accent,{BackgroundColor3=Color3.fromRGB(60,55,80)},0.25):Play() end end)

followToggle.btn.MouseButton1Click:Connect(function() followEnabled=not followEnabled if followEnabled then if not selectedFollowPlayer or selectedFollowPlayer=="No Player" then Window.Notify("ERROR","Pilih player dulu!",Color3.fromRGB(248,113,113),2) followEnabled=false return end tw(followToggle.track,{BackgroundColor3=ACCENT},0.2):Play() tw(followToggle.dot,{Position=UDim2.new(1,-21,0.5,-9)},0.25,Enum.EasingStyle.Back):Play() tw(followToggle.accent,{BackgroundColor3=ACCENT},0.2):Play() Window.Notify("FOLLOW","Follow ON: "..selectedFollowPlayer,ACCENT,2) task.spawn(function() while followEnabled do if selectedFollowPlayer then local target=Players:FindFirstChild(selectedFollowPlayer) if target and target.Character and target.Character:FindFirstChild("HumanoidRootPart") then local hrp=target.Character.HumanoidRootPart walkDirect(V3(hrp.Position.X,3.5,hrp.Position.Z),hrp.Position,false) end end task.wait(0.15) end end) else tw(followToggle.track,{BackgroundColor3=Color3.fromRGB(34,30,50)},0.2):Play() tw(followToggle.dot,{Position=UDim2.new(0,3,0.5,-9)},0.25,Enum.EasingStyle.Back):Play() tw(followToggle.accent,{BackgroundColor3=Color3.fromRGB(60,55,80)},0.2):Play() Window.Notify("FOLLOW","OFF",DIM,2) end end)

local autoBestOn=false
autoBestToggle.btn.MouseButton1Click:Connect(function() autoBestOn=not autoBestOn if autoBestOn then tw(autoBestToggle.track,{BackgroundColor3=ACCENT},0.2):Play() tw(autoBestToggle.dot,{Position=UDim2.new(1,-21,0.5,-9)},0.25,Enum.EasingStyle.Back):Play() tw(autoBestToggle.accent,{BackgroundColor3=ACCENT},0.2):Play() Window.Notify("ANIMAL","Auto Best ON - 1s loop",ACCENT,2) task.spawn(function() while autoBestOn do pcall(function() RS:WaitForChild("PetsInventoryRemote"):FireServer("EquipBest",nil) end) task.wait(1) end end) else tw(autoBestToggle.track,{BackgroundColor3=Color3.fromRGB(34,30,50)},0.2):Play() tw(autoBestToggle.dot,{Position=UDim2.new(0,3,0.5,-9)},0.25,Enum.EasingStyle.Back):Play() tw(autoBestToggle.accent,{BackgroundColor3=Color3.fromRGB(60,55,80)},0.2):Play() Window.Notify("ANIMAL","OFF",DIM,2) end end)

local function resetCharOnce() pcall(function() local char=plr.Character local hum=char and char:FindFirstChildOfClass("Humanoid") if hum then hum.Health=0 else if char then char:BreakJoints() end end end) end
halloweenToggle.btn.MouseButton1Click:Connect(function() halloweenEnabled=not halloweenEnabled if halloweenEnabled then tw(halloweenToggle.track,{BackgroundColor3=Color3.fromRGB(255,140,0)},0.2):Play() tw(halloweenToggle.dot,{Position=UDim2.new(1,-21,0.5,-9)},0.25,Enum.EasingStyle.Back):Play() tw(halloweenToggle.accent,{BackgroundColor3=Color3.fromRGB(255,140,0)},0.2):Play() Window.Notify("HALLOWEEN","Auto Halloween ON",Color3.fromRGB(255,140,0),2) task.spawn(function() while halloweenEnabled do local clue,pos=getClosestClue() if clue and pos then cachedCluePos=pos lastClueSeen=tick() if not halloweenActive then halloweenActive=true hasResetThisEvent=false Window.Notify("HALLOWEEN","Event Muncul! Reset Char 1x",Color3.fromRGB(255,140,0),3) end if not hasResetThisEvent then hasResetThisEvent=true resetCharOnce() task.wait(2) continue end local targetPos=V3(pos.X,3.5,pos.Z) pcall(function() walkDirect(targetPos,pos,false) end) task.wait(halloweenStay) else if halloweenActive and (tick()-lastClueSeen)>10 then halloweenActive=false hasResetThisEvent=false cachedCluePos=nil Window.Notify("HALLOWEEN","Event Selesai (10s no clue) - Balik Break Egg",DIM,3) end task.wait(0.5) end end end) else tw(halloweenToggle.track,{BackgroundColor3=Color3.fromRGB(34,30,50)},0.2):Play() tw(halloweenToggle.dot,{Position=UDim2.new(0,3,0.5,-9)},0.25,Enum.EasingStyle.Back):Play() tw(halloweenToggle.accent,{BackgroundColor3=Color3.fromRGB(60,55,80)},0.2):Play() halloweenActive=false hasResetThisEvent=false Window.Notify("HALLOWEEN","OFF",DIM,2) end end)

local fastBreakOn=false local fastBreakConn=nil
local function setFastBreakAttribute(state) pcall(function() plr:SetAttribute("FastSwingOwned",state) end) pcall(function() if plr.Character then plr.Character:SetAttribute("FastSwingOwned",state) end end) end
fastBreakToggle.btn.MouseButton1Click:Connect(function() fastBreakOn=not fastBreakOn if fastBreakOn then tw(fastBreakToggle.track,{BackgroundColor3=ACCENT},0.2):Play() tw(fastBreakToggle.dot,{Position=UDim2.new(1,-21,0.5,-9)},0.25,Enum.EasingStyle.Back):Play() tw(fastBreakToggle.accent,{BackgroundColor3=ACCENT},0.2):Play() setFastBreakAttribute(true) if fastBreakConn then fastBreakConn:Disconnect() end fastBreakConn=RunService.Heartbeat:Connect(function() if plr:GetAttribute("FastSwingOwned")~=true then setFastBreakAttribute(true) end end) else tw(fastBreakToggle.track,{BackgroundColor3=Color3.fromRGB(34,30,50)},0.2):Play() tw(fastBreakToggle.dot,{Position=UDim2.new(0,3,0.5,-9)},0.25,Enum.EasingStyle.Back):Play() tw(fastBreakToggle.accent,{BackgroundColor3=Color3.fromRGB(60,55,80)},0.2):Play() if fastBreakConn then fastBreakConn:Disconnect() fastBreakConn=nil end setFastBreakAttribute(false) end end)

local noRagdollOn=false local ragdollConns={}
local function enableNoRagdoll() for _,c in ipairs(ragdollConns) do pcall(function() c:Disconnect() end) end ragdollConns={} local char=plr.Character local hum=char and char:FindFirstChildOfClass("Humanoid") if hum then pcall(function() hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll,false) hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown,false) hum.BreakJointsOnDeath=false hum.PlatformStand=false end) table.insert(ragdollConns,hum.StateChanged:Connect(function(_,new) if new==Enum.HumanoidStateType.Ragdoll or new==Enum.HumanoidStateType.FallingDown then hum:ChangeState(Enum.HumanoidStateType.GettingUp) end end)) end table.insert(ragdollConns,RunService.Heartbeat:Connect(function() local c=plr.Character local h=c and c:FindFirstChildOfClass("Humanoid") if h then if h:GetState()==Enum.HumanoidStateType.Ragdoll or h:GetState()==Enum.HumanoidStateType.FallingDown then h:ChangeState(Enum.HumanoidStateType.GettingUp) h.PlatformStand=false end h:SetStateEnabled(Enum.HumanoidStateType.Ragdoll,false) h:SetStateEnabled(Enum.HumanoidStateType.FallingDown,false) end end)) end
local function disableNoRagdoll() for _,c in ipairs(ragdollConns) do pcall(function() c:Disconnect() end) end ragdollConns={} local hum=plr.Character and plr.Character:FindFirstChildOfClass("Humanoid") if hum then pcall(function() hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll,true) hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown,true) hum.BreakJointsOnDeath=true end) end end
ragdollToggle.btn.MouseButton1Click:Connect(function() noRagdollOn=not noRagdollOn if noRagdollOn then tw(ragdollToggle.track,{BackgroundColor3=ACCENT},0.2):Play() tw(ragdollToggle.dot,{Position=UDim2.new(1,-21,0.5,-9)},0.25,Enum.EasingStyle.Back):Play() tw(ragdollToggle.accent,{BackgroundColor3=ACCENT},0.2):Play() enableNoRagdoll() else tw(ragdollToggle.track,{BackgroundColor3=Color3.fromRGB(34,30,50)},0.2):Play() tw(ragdollToggle.dot,{Position=UDim2.new(0,3,0.5,-9)},0.25,Enum.EasingStyle.Back):Play() tw(ragdollToggle.accent,{BackgroundColor3=Color3.fromRGB(60,55,80)},0.2):Play() disableNoRagdoll() end end)

local antiMentalOn=false local antiMentalConns={}
local function enableAntiMental() for _,c in ipairs(antiMentalConns) do pcall(function() c:Disconnect() end) end antiMentalConns={} table.insert(antiMentalConns,RunService.Heartbeat:Connect(function() local char=plr.Character local hrp=char and char:FindFirstChild("HumanoidRootPart") if not hrp then return end local vel=hrp.AssemblyLinearVelocity local flat=V3(vel.X,0,vel.Z).Magnitude if flat>35 then hrp.AssemblyLinearVelocity=V3(0,vel.Y,0) hrp.AssemblyAngularVelocity=Vector3.zero pcall(function() hrp.Velocity=V3(0,hrp.Velocity.Y,0) end) end if hrp.AssemblyAngularVelocity.Magnitude>20 then hrp.AssemblyAngularVelocity=Vector3.zero end end)) end
local function disableAntiMental() for _,c in ipairs(antiMentalConns) do pcall(function() c:Disconnect() end) end antiMentalConns={} end
antiMentalToggle.btn.MouseButton1Click:Connect(function() antiMentalOn=not antiMentalOn if antiMentalOn then tw(antiMentalToggle.track,{BackgroundColor3=ACCENT},0.2):Play() tw(antiMentalToggle.dot,{Position=UDim2.new(1,-21,0.5,-9)},0.25,Enum.EasingStyle.Back):Play() tw(antiMentalToggle.accent,{BackgroundColor3=ACCENT},0.2):Play() enableAntiMental() else tw(antiMentalToggle.track,{BackgroundColor3=Color3.fromRGB(34,30,50)},0.2):Play() tw(antiMentalToggle.dot,{Position=UDim2.new(0,3,0.5,-9)},0.25,Enum.EasingStyle.Back):Play() tw(antiMentalToggle.accent,{BackgroundColor3=Color3.fromRGB(60,55,80)},0.2):Play() disableAntiMental() end end)

plr.CharacterAdded:Connect(function(char) task.wait(0.5) local hum=char:WaitForChild("Humanoid",15) if hum then local realSpeed=hum.WalkSpeed sliderSpeed=realSpeed hum:SetAttribute("BaseSpeed",realSpeed) if walkSpeedSliderRef then walkSpeedSliderRef.setValue(realSpeed) end end task.wait(0.5) if noRagdollOn then enableNoRagdoll() end if antiMentalOn then enableAntiMental() end if fastBreakOn then setFastBreakAttribute(true) end if clearOnRespawn then clearAllEsp() end if espEnabled then task.wait(0.5) refreshAllEsp() end end)
do local hum=plr.Character and plr.Character:FindFirstChildOfClass("Humanoid") if hum then sliderSpeed=hum.WalkSpeed hum:SetAttribute("BaseSpeed",hum.WalkSpeed) end end
RunService.Heartbeat:Connect(function() local hum=plr.Character and plr.Character:FindFirstChildOfClass("Humanoid") if hum then if math.abs(hum.WalkSpeed-sliderSpeed)>0.1 then hum.WalkSpeed=sliderSpeed end end end)
